  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB0LD_0LB1LC_1RD0LC_0RD1LA
      with (l := [SWin 2]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB0LD_0LB1LC_1RD0LC_0RD1LA
      with (l := [SWin 3; SCycL 1 0; SWin 2]).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB0LD_0LB1LC_1RD0LC_0RD1LA
      with (l := [SWin 3; SCycL 1 0; SWin 2; SCycR 1; SWin 2]).
    vm_compute; reflexivity.
Qed.

