Qed.

Theorem qhtrm_1RB0LD_0LC1RA_1LD1RC_0RC1LA : NonHalt tmm_1RB0LD_0LC1RA_1LD1RC_0RC1LA /\ QHBoundTr 32779478 tmm_1RB0LD_0LC1RA_1LD1RC_0RC1LA /\ QuasiHaltsTr tmm_1RB0LD_0LC1RA_1LD1RC_0RC1LA.
