Theorem qhtr_1RB0LD_0LC1RA_1LD1RC_0RC1LA : NonHalt tm_1RB0LD_0LC1RA_1LD1RC_0RC1LA /\ QHBoundTr 32779478 tm_1RB0LD_0LC1RA_1LD1RC_0RC1LA /\ QuasiHaltsTr tm_1RB0LD_0LC1RA_1LD1RC_0RC1LA.
