(** The lap ends on [S0] where the anchor has [] -- one trailing blank,
    which [lift] cannot see. *)
Lemma gei_1RB0LD_0RC1LA_1LD1RC_0RC1LA : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A1_1RB0LD_0RC1LA_1LD1RC_0RC1LA) = lift (Cc (Pos.succ p)).
