Lemma geo_1RB0LD_0RC1LA_1LD1RC_0RC1LA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0LD_0RC1LA_1LD1RC_0RC1LA) = lift (Cc (Pos.succ p)).
