    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0LD_0RC1LA_1LD1RC_0RC1LA B0_1RB0LD_0RC1LA_1LD1RC_0RC1LA B1_1RB0LD_0RC1LA_1LD1RC_0RC1LA 4 13 p j' [] []).
    + exact run_ovf_1RB0LD_0RC1LA_1LD1RC_0RC1LA.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0LD_0RC1LA_1LD1RC_0RC1LA p j' E).
    + exact (geo_1RB0LD_0RC1LA_1LD1RC_0RC1LA p j' E).
    + lia.
