  - exact bootq_1RB0LD_0RC1LA_1LD1RC_0RC1LA.
  - intros p _. apply lap_1RB0LD_0RC1LA_1LD1RC_0RC1LA.
  - intros t Ht p _. apply fire_1RB0LD_0RC1LA_1LD1RC_0RC1LA. exact Ht.
  - exact wit_1RB0LD_0RC1LA_1LD1RC_0RC1LA.
  - apply qcleb_QC_12. reflexivity.
Qed.

Theorem qhtr_1RB0LD_0RC1LA_1LD1RC_0RC1LA : NonHalt tm_1RB0LD_0RC1LA_1LD1RC_0RC1LA /\ QHBoundTr 32779478 tm_1RB0LD_0RC1LA_1LD1RC_0RC1LA /\ QuasiHaltsTr tm_1RB0LD_0RC1LA_1LD1RC_0RC1LA.
