    apply (lap_of_run tm Cc true true cho_1RB0LD_0RC1LC_1LD1RC_0RC1LA B0_1RB0LD_0RC1LC_1LD1RC_0RC1LA B1_1RB0LD_0RC1LC_1LD1RC_0RC1LA 4 21 p j' [] []).
