Definition mk_1RB0LD_1LB1LC_1LD1RC_0RC1LA (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_1RB0LD_1LB1LC_1LD1RC_0RC1LA.

(** 1RB0LD_1LB1LC_1LD1RC_0RC1LA *)
(** 1RB0LD_1LB1LC_1LD1RC_0RC1LA -- the real machine (its counter grows RIGHT). *)
Definition tm_1RB0LD_1LB1LC_1LD1RC_0RC1LA : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S0 DL StD
  | StB, S0 => mk S1 DL StB | StB, S1 => mk S1 DL StC
  | StC, S0 => mk S1 DL StD | StC, S1 => mk S1 DR StC
  | StD, S0 => mk S0 DR StC | StD, S1 => mk S1 DL StA end.

(** Its mirror 1LB0RD_1RB1RC_1RD1LC_0LC1RA: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_1RB0LD_1LB1LC_1LD1RC_0RC1LA : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => mk S0 DR StD
  | StB, S0 => mk S1 DR StB | StB, S1 => mk S1 DR StC
  | StC, S0 => mk S1 DR StD | StC, S1 => mk S1 DL StC
  | StD, S0 => mk S0 DL StC | StD, S1 => mk S1 DR StA end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB0LD_1LB1LC_1LD1RC_0RC1LA : list Instr := [(StB, S0)].
Definition tmw_1RB0LD_1LB1LC_1LD1RC_0RC1LA : TM := tm_wrap_trs tmm_1RB0LD_1LB1LC_1LD1RC_0RC1LA pins_1RB0LD_1LB1LC_1LD1RC_0RC1LA.
Local Notation tm := tmw_1RB0LD_1LB1LC_1LD1RC_0RC1LA.

Lemma mirror_ok_1RB0LD_1LB1LC_1LD1RC_0RC1LA : mirror_tm tm_1RB0LD_1LB1LC_1LD1RC_0RC1LA = tmm_1RB0LD_1LB1LC_1LD1RC_0RC1LA.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_1RB0LD_1LB1LC_1LD1RC_0RC1LA (p : positive) : cconf := (StC, (Ap_Alph_10_11_11 p ++ [S0], S0, [S1;S1])).
