Lemma fire_1RB0LD_1LC0LA_0RC1LD_1RC1LA : forall t, ~ In t pins_1RB0LD_1LC0LA_0RC1LD_1RC1LA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
