Lemma fire_1RB0LD_1LC0RB_0LC1LD_0RD1RA : forall t, ~ In t pins_1RB0LD_1LC0RB_0LC1LD_0RD1RA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
