    exists (2 * j' + 8). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB0LD_1LC0RB_0LC1LD_1RC1RA P0_1RB0LD_1LC0RB_0LC1LD_1RC1RA P1_1RB0LD_1LC0RB_0LC1LD_1RC1RA 2 8
