(** ** Bootstrap *)

Lemma bootq_1RB0LD_1LC0RB_0LC1LD_1RC1RA : stepn tmm_1RB0LD_1LC0RB_0LC1LD_1RC1RA 8 InitES = Some (lift (Cc 1)).
