  apply (fire_of_run_instr tm Cc true true l B0_1RB0LD_1LC0RB_0LC1LD_1RC1RA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0LD_1LC0RB_0LC1LD_1RC1RA p j E)].
