Theorem qhtr_1RB0LD_1LC0RB_0LC1LD_1RC1RA : NonHalt tm_1RB0LD_1LC0RB_0LC1LD_1RC1RA /\ QHBoundTr 32779478 tm_1RB0LD_1LC0RB_0LC1LD_1RC1RA /\ QuasiHaltsTr tm_1RB0LD_1LC0RB_0LC1LD_1RC1RA.
