Lemma gz_1RB0LD_1LC0RB_0LC1LD_1RD1RA : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Kp q0 ++ [S0]) [] 0 Z0_1RB0LD_1LC0RB_0LC1LD_1RD1RA /\
