  unfold Cc_1RB0LD_1LC0RB_0LC1LD_1RD1RA, cden, Z0_1RB0LD_1LC0RB_0LC1LD_1RD1RA, Z1_1RB0LD_1LC0RB_0LC1LD_1RD1RA; cbn [c_st c_l c_h c_r].
