Lemma gp_1RB0LD_1LC0RB_0LC1LD_1RD1RA : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Kp q0 ++ [S0]) [] j P0_1RB0LD_1LC0RB_0LC1LD_1RD1RA /\
