Lemma lapi_1RB0LD_1LC0RB_0LC1LD_1RD1RA : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_1RB0LD_1LC0RB_0LC1LD_1RD1RA p q0 E) as (HA & HB).
    exists (0 * 0 + 6). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_1RB0LD_1LC0RB_0LC1LD_1RD1RA Z0_1RB0LD_1LC0RB_0LC1LD_1RD1RA Z1_1RB0LD_1LC0RB_0LC1LD_1RD1RA 0 6
               run_z_1RB0LD_1LC0RB_0LC1LD_1RD1RA (Kp q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_1RB0LD_1LC0RB_0LC1LD_1RD1RA p j' q0 E) as (HA & HB).
    exists (2 * j' + 8). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB0LD_1LC0RB_0LC1LD_1RD1RA P0_1RB0LD_1LC0RB_0LC1LD_1RD1RA P1_1RB0LD_1LC0RB_0LC1LD_1RD1RA 2 8
               run_p_1RB0LD_1LC0RB_0LC1LD_1RD1RA (Kp q0 ++ [S0]) [] j'
               ltac:(discriminate) ltac:(reflexivity)).
