    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LD_1LC1RA_0LD1LB_0RA1LD [SCycL 2 0; SWin 4; SWinL 8; SCycR 2; SWinR 1] (StD, S0) ltac:(vm_compute; reflexivity)
