(** ** The lap *)

Lemma lap_1RB0LD_1LC1RA_0RD1LB_0RB1LD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0LD_1LC1RA_0RD1LB_0RB1LD p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0LD_1LC1RA_0RD1LB_0RB1LD B0_1RB0LD_1LC1RA_0RD1LB_0RB1LD B1_1RB0LD_1LC1RA_0RD1LB_0RB1LD 4 12 p j' [] []).
    + exact run_ovf_1RB0LD_1LC1RA_0RD1LB_0RB1LD.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0LD_1LC1RA_0RD1LB_0RB1LD p j' E).
    + exact (geo_1RB0LD_1LC1RA_0RD1LB_0RB1LD p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma bootq_1RB0LD_1LC1RA_0RD1LB_0RB1LD : stepn tmm_1RB0LD_1LC1RA_0RD1LB_0RB1LD 10 InitES = Some (lift (Cc 1)).
Proof.
  assert (H : match csteps tmm_1RB0LD_1LC1RA_0RD1LB_0RB1LD 10 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tmm_1RB0LD_1LC1RA_0RD1LB_0RB1LD 10 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_1RB0LD_1LC1RA_0RD1LB_0RB1LD : existsb (fun tg => cfires tmm_1RB0LD_1LC1RA_0RD1LB_0RB1LD c0 10 tg) pins_1RB0LD_1LC1RA_0RD1LB_0RB1LD = true.
